/**
 * 工具元数据 - 集中管理所有工具信息
 *
 * 加新工具只需 3 步:
 * 1. 在 app/tools/<slug>/ 新建 page.tsx
 * 2. 在这里加一条配置
 * 3. 首页、导航、sitemap 会自动更新
 *
 * SEO 关键字段说明:
 * - keywords: 目标关键词,用于 meta keywords 和首页标签
 * - searchIntent: 'commercial' | 'informational' | 'navigational'
 *     commercial 工具(有花钱场景)广告主出价高,RPM 高,优先做
 */

