// 图标解析已拆分至 lib/tool-icons.ts(客户端安全的轻量模块),此处 re-export 保持兼容
export { getToolIcon } from './tool-icons'

export function getTool(slug: string): ToolMeta | undefined {
  return tools.find((t) => t.slug === slug)
}

/** 获取所有已上线的工具(用于首页、sitemap) */
let publishedCache: ToolMeta[] | null = null
export function getPublishedTools(): ToolMeta[] {
  if (!publishedCache) publishedCache = tools.filter((t) => t.published)
  return publishedCache
}

/**
 * 获取置顶热门工具(用于首页 "🔥 Popular Tools" 模块)。
 * 顺序与 tools.ts 中声明顺序一致(配置时即可控制展示顺序)。
 * 未标记 featured 的工具自然不出现。
 */
export function getFeaturedTools(): ToolMeta[] {
  return tools.filter((t) => t.published && t.featured)
}

/** 获取所有工具(含未上线,用于 sitemap 全量收录 - 改为 published 的话只收录已上线) */
export function getAllToolSlugs(): string[] {
  return tools.filter((t) => t.published).map((t) => t.slug)
}

/** 按分类分组 */
export function getToolsByCategory(): Record<string, ToolMeta[]> {
  const grouped: Record<string, ToolMeta[]> = {}
  for (const tool of getPublishedTools()) {
    if (!grouped[tool.category]) grouped[tool.category] = []
    grouped[tool.category].push(tool)
  }
  return grouped
}

/**
 * 相关工具内部排序:featured 优先,其次按 slug 字典序做稳定回退。
 * 让置顶工具优先在「Related Tools」矩阵里获得内链,提升其权重传递效率。
 */
function rankRelated(arr: ToolMeta[]): ToolMeta[] {
  return [...arr].sort((a, b) => {
    const fa = a.featured ? 0 : 1
    const fb = b.featured ? 0 : 1
    if (fa !== fb) return fa - fb
    return a.slug < b.slug ? -1 : a.slug > b.slug ? 1 : 0
  })
}

/**
 * 获取某工具的相关工具(用于工具详情页底部「Related Tools」内链矩阵)
 *
 * 匹配逻辑(pSEO + 内链权重传递优化):
 *  1. 同分类下的其他工具(剔除当前工具本身),featured 工具排在最前;
 *  2. 最多展示 `limit` 个(默认 4,与 RelatedTools 网格 4 列对齐);
 *  3. 若同分类数量不足,用全站热门工具(featured)补齐,保证矩阵永远满格,
 *     避免某些工具页内链过稀导致权重孤岛。
 *
 * 顺序稳定且确定:相同输入永远输出相同列表(SSR 与 build 结果一致)。
 */
export function getRelatedTools(slug: string, limit = 4): ToolMeta[] {
  const current = getTool(slug)
  if (!current) return []

  const published = getPublishedTools()

  // ① 同分类的其他工具(featured 优先)
  const sameCategory = published.filter(
    (t) => t.slug !== slug && t.category === current.category,
  )
  const rankedSame = rankRelated(sameCategory)
  const picked = [...rankedSame.slice(0, limit)]

  // ② 名额不足时,用全站热门工具(featured)补齐,排除当前工具与已选中工具
  if (picked.length < limit) {
    const pickedSlugs = new Set(picked.map((t) => t.slug))
    const fallback = published.filter(
      (t) => t.slug !== slug && !pickedSlugs.has(t.slug) && t.featured,
    )
    picked.push(...fallback.slice(0, limit - picked.length))
  }

  // ③ 若热门仍不足(极端边缘情况),用任意其它已上线工具兜底补满
  if (picked.length < limit) {
    const pickedSlugs = new Set(picked.map((t) => t.slug))
    const fillers = published.filter((t) => t.slug !== slug && !pickedSlugs.has(t.slug))
    picked.push(...fillers.slice(0, limit - picked.length))
  }

  return picked.slice(0, limit)
}

/**
 * 获取某工具「工作流下一步」推荐 slug 列表(结果区 Next Steps 胶囊用)。
 *
 *  1. 显式配置的 tool.nextTools 优先(已过滤未上线/自身/不存在者);
 *  2. 未配置或过滤后为空 → 回退同分类前 2 款(复用 getRelatedTools 的
 *     featured 优先排序,顺序确定,build 产物稳定)。
 */
export function getNextToolSlugs(slug: string): string[] {
  const current = getTool(slug)
  if (!current) return []

  const publishedSlugs = new Set(getPublishedTools().map((t) => t.slug))
  const explicit = (current.nextTools ?? []).filter(
    (s) => s !== slug && publishedSlugs.has(s),
  )
  if (explicit.length > 0) return explicit

  return getRelatedTools(slug, 2).map((t) => t.slug)
}
